import { BOARD_SCRIPT } from './board-script'
import { LANGS, ZH_TW } from './i18n'
import type { Strings } from './i18n'
import { RELEASED } from './released'
import type { ReleasedKind } from './released'
import { sha256 } from './sha256'
import { STRINGS } from './strings'
import { boardRun, geminiBoardCommand, normalizeCommandPath, opencodeBoardCommand } from './board-commands'

// The reporter script an agent's hook runs, written beside progress.md by `/progress
// connect`: it saves what the hook hands over into the inbox and clears files older than two
// days. No dependencies: POSIX sh on macOS and Linux, Windows PowerShell 5.1 on Windows.

// Arguments: the agent's name, `turn` or `end`, then optionally the JSON itself (as Codex's
// legacy notify passes it) instead of on stdin.
export const reporterSh = (inbox: string): string => `#!/bin/sh
# Written by the Agent Board plugin (/progress connect). An agent's hook runs it at the end of
# a turn or a session; the Agent Board pane reads what it saves.
exec 2>/dev/null
agent="\${1:-agent}"
event="\${2:-turn}"
[ $# -gt 0 ] && shift
[ $# -gt 0 ] && shift
dir=${shellQuote(inbox)}
mkdir -p "$dir" 2>/dev/null
file="$dir/$agent-$event-$(date +%s)-$$"
if [ $# -gt 0 ]; then
  printf '%s' "$1" > "$file.tmp"
elif [ ! -t 0 ]; then
  cat > "$file.tmp"
fi
[ -s "$file.tmp" ] && mv "$file.tmp" "$file.json"
rm -f "$file.tmp"
find "$dir" -name '*.json' -mtime +2 -exec rm -f {} +
# Quiet for every agent but Cursor, which expects a JSON answer; Gemini CLI reads stderr
# when stdout is empty, so that stays quiet too. Always exit 0: some agents read exit 2 as
# "keep going".
[ "$agent" = cursor ] && printf '{}\\n'
exit 0
`

// The inbox is found from the script's own folder (both sit beside progress.md), so the
// script holds no path: PowerShell 5.1 reads a file with no byte-order mark in the system's
// code page, which would turn a home folder named in Chinese into a different folder.
export const reporterPs1 = (): string => `# Written by the Agent Board plugin (/progress connect). An agent's hook runs it at the end of
# a turn or a session; the Agent Board pane reads what it saves.
param([string]$Agent = 'agent', [string]$Event = 'turn', [string]$Payload = '')
$ErrorActionPreference = 'SilentlyContinue'
$dir = Join-Path $PSScriptRoot 'progress-inbox'
New-Item -ItemType Directory -Force -Path $dir | Out-Null
if ($Payload -eq '' -and [Console]::IsInputRedirected) {
  [Console]::InputEncoding = [Text.Encoding]::UTF8
  $Payload = [Console]::In.ReadToEnd()
}
if ($Payload.Trim() -ne '') {
  $name = '{0}-{1}-{2}-{3}' -f $Agent, $Event, [DateTimeOffset]::Now.ToUnixTimeMilliseconds(), $PID
  $tmp = Join-Path $dir ($name + '.tmp')
  [IO.File]::WriteAllText($tmp, $Payload, (New-Object Text.UTF8Encoding $false))
  Move-Item -Force $tmp (Join-Path $dir ($name + '.json'))
}
Get-ChildItem -Path $dir -Filter '*.json' | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-2) } | Remove-Item -Force
if ($Agent -eq 'cursor') { '{}' }
exit 0
`

export const shellQuote = (text: string): string => `'${text.replace(/'/g, `'\\''`)}'`

export const psQuote = (text: string): string => `'${text.replace(/'/g, "''")}'`

// The command line a hook runs for one agent and event. When the script is gone (the
// person deleted ~/.claude, or uninstalled without `/progress connect remove`), sh exits 2,
// which Gemini CLI, Codex, Grok Build and Muse Code read as "block" and run the agent
// again, for ever; `|| true` keeps it at 0. PowerShell exits 64 for a missing file, which
// they only warn about.
export const reportCommand = (script: string, agent: string, event: 'turn' | 'end', isWindows: boolean): string =>
  isWindows
    ? `powershell -NoProfile -ExecutionPolicy Bypass -File "${script}" ${agent} ${event}`
    : `sh ${shellQuote(script)} ${agent} ${event} || true`

// A hook command this plugin wrote: it runs the reporter script by its path, so a person's
// own `my-progress-report.sh` is not taken for ours.
const OURS = /(?:^|[\\/'"\s])progress-report\.(?:sh|ps1)(?:\\?['"])?(?:\s|$)/

// Whether a config already runs our reporter, whatever else taking our hooks out would tidy.
export const hasOurHook = (text: string): boolean => OURS.test(text)

// Whether the computer is Windows: Windows sets OS=Windows_NT in every shell (Git Bash too),
// and a path on a drive letter says so even when written with forward slashes
// (`C:/Users/me/progress.md`). Backslashes alone are no sign either way.
export const isWindowsHost = (os: string | undefined, path: string): boolean => os === 'Windows_NT' || /^[A-Za-z]:[\\/]/.test(path)

type Json = Record<string, unknown>

const isRecord = (value: unknown): value is Json => value !== null && typeof value === 'object' && !Array.isArray(value)

const commandOf = (entry: unknown): string => {
  if (!isRecord(entry)) return ''
  if (typeof entry.command === 'string') return entry.command
  if (Array.isArray(entry.command)) return entry.command.join(' ')

  return ''
}

// Hooks grouped the way Claude Code writes them (Codex, Gemini CLI, Grok Build and Muse
// Code take the same shape): `hooks.<Event>` is a list of `{ matcher?, hooks: [{ type,
// command }] }`. Ours replaces any earlier one of ours; everything else stays.
export const withGroupedHook = (config: Json, event: string, command: string, extra: Json = {}): Json => {
  const hooks = isRecord(config.hooks) ? config.hooks : {}
  const groups = Array.isArray(hooks[event]) ? (hooks[event] as unknown[]) : []
  const kept = groups.filter(group => !(isRecord(group) && Array.isArray(group.hooks) && group.hooks.some(one => OURS.test(commandOf(one)))))
  const ours = { hooks: [{ ...(typeof extra.name === 'string' ? { name: extra.name } : {}), type: 'command', command, ...extra }] }

  return { ...config, hooks: { ...hooks, [event]: [...kept, ours] } }
}

// Cursor's shape: `{ version: 1, hooks: { <event>: [{ command }] } }`.
export const withFlatHook = (config: Json, event: string, command: string): Json => {
  const hooks = isRecord(config.hooks) ? config.hooks : {}
  const list = Array.isArray(hooks[event]) ? (hooks[event] as unknown[]) : []
  const kept = list.filter(one => !OURS.test(commandOf(one)))

  return { version: 1, ...config, hooks: { ...hooks, [event]: [...kept, { command }] } }
}

// Every hook of ours taken out, in either shape; an event left empty goes too.
export const withoutOurHooks = (config: Json): Json => {
  if (!isRecord(config.hooks)) return config
  const hooks: Json = {}
  for (const [event, value] of Object.entries(config.hooks)) {
    if (!Array.isArray(value)) {
      hooks[event] = value
      continue
    }
    const kept = value
      .map(entry => {
        if (isRecord(entry) && Array.isArray(entry.hooks)) {
          const inner = entry.hooks.filter(one => !OURS.test(commandOf(one)))
          return inner.length === 0 ? null : { ...entry, hooks: inner }
        }
        return OURS.test(commandOf(entry)) ? null : entry
      })
      .filter(entry => entry !== null)
    if (kept.length > 0) hooks[event] = kept
  }

  return { ...config, hooks }
}

// A number's significant digits, without sign, point, exponent or the zeros around them.
const digitsOf = (number: string): string => number.replace(/[eE].*$/, '').replace(/[-.]/g, '').replace(/^0+/, '').replace(/0+$/, '')

// A number JSON.parse cannot hold as written: an integer past 2^53 (a Discord or Telegram
// id), one past a double's range (1e400, 1e-400), or more digits than a double keeps.
// Written back, it would come out as a different number: the digits a double prints for
// itself are not the ones written.
const losesNumbers = (text: string): boolean =>
  (text.replace(/"(?:[^"\\]|\\.)*"/g, '""').match(/-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?/g) ?? []).some(literal => {
    const value = Number(literal)
    return !Number.isFinite(value) || digitsOf(value.toExponential()) !== digitsOf(literal)
  })

// A config file read as JSON: `{}` when it is missing or empty, null when it holds
// something that is not a JSON object (comments, a typo) or a number it would change, which
// is then left alone.
export const readConfig = (text: string): Json | null => {
  if (text.trim() === '') return {}
  try {
    const parsed: unknown = JSON.parse(text)
    return isRecord(parsed) && !losesNumbers(text) ? parsed : null
  } catch {
    return null
  }
}

// The config written back, or the text as it was when nothing in it changed, so a file the
// person or the agent formats its own way is not rewritten (and announced) at every start.
const writeChanged = (text: string, before: Json, after: Json): string =>
  JSON.stringify(after) === JSON.stringify(before) ? text : writeConfig(after)

export const writeConfig = (config: Json): string => `${JSON.stringify(config, null, 2)}\n`

// The section setup --agents puts in an agent's instruction file, under the plugin's name or
// the one it had before (claude-progress-pane). A hook replaces it, so the agent's work does
// not show twice.
const SECTION = /\n*<!-- (agent-board|claude-progress-pane):start -->[\s\S]*?<!-- \1:end -->\n*/g

export const withoutSection = (text: string): string => {
  const after = text.replace(SECTION, '\n')

  return after === text ? text : after.replace(/^\n+/, '')
}

// Where each agent keeps what `/progress connect` changes, and how. `dir` says the agent is
// installed (its folder under the home directory); `edit` turns the file's text into the
// new text, or null when the file cannot be read as JSON and is left alone.
export type ConnectContext = { home: string; sep: string; isWindows: boolean; script: string; inbox: string; codexHome: string; grokHome: string; hermesHome: string; openclawHome: string; opencodeHome?: string; board?: string; s?: Strings }

export type AgentHook = {
  agent: string
  // '' for a file that only shows the board (a board command, the shared skill): it is
  // written, but connecting an agent means its turns reach the board, so it is never named.
  label: string
  dir: string
  // Any of these says the agent is installed, when there is more than one place to look.
  dirs?: string[]
  file: string
  // The file an earlier name of the plugin wrote instead, taken away when connecting or removing.
  old?: string
  generated?: boolean
  edit: (text: string, remove: boolean, previous?: string) => string | null | typeof DELETE | typeof COLLISION
}

// What `edit` answers for a file of ours that removing takes away whole.
export const DELETE = Symbol('delete')
export const COLLISION = Symbol('collision')

// Whole generated files are replaced only when their exact bytes are known. The stored
// previous output permits upgrades; legacy templates (a list, or a check such as
// `isReleased`) permit adoption before that record existed. A familiar path or a copied
// header is not ownership of the rest of a file.
export const generatedFile = (content: string, legacy: readonly string[] | ((text: string) => boolean) = []): AgentHook['edit'] => (text, remove, previous) => {
  const isKnown = (): boolean => (typeof legacy === 'function' ? legacy(text) : legacy.includes(text))
  if (text !== '' && text !== content && text !== previous && !isKnown()) return COLLISION

  return remove ? (text === '' ? null : DELETE) : content
}

const join = (ctx: ConnectContext, ...parts: string[]): string => [ctx.home, ...parts].join(ctx.sep)

// Other tools (Orca among them) put hooks in ~/.grok/hooks for a Grok Build that may never
// be installed, so the folder alone is no sign of it: Grok's own config or sessions are.
const grokSigns = (ctx: ConnectContext): string[] => ['config.toml', 'sessions', '.metadata_version', 'agent_id'].map(name => [ctx.grokHome, name].join(ctx.sep))

const jsonEdit =
  (add: (config: Json) => Json) =>
  (text: string, remove: boolean): string | null => {
    const config = readConfig(text)
    if (config === null) return null
    return writeChanged(text, config, remove ? withoutOurHooks(config) : add(withoutOurHooks(config)))
  }

// Hermes Agent keeps its hooks in YAML: `hooks.<event>` is a list of `{ command, timeout }`.
// With no YAML parser here, ours go in as one flow-style line each, found again by the
// reporter script's name, and a `hooks:` written in a shape this cannot follow (flow style)
// is left alone. The empty map `hooks: {}` is the one flow-style value it can follow: Hermes
// writes that into a new config.yaml, and it holds nothing to keep.
// A comment runs to the line end, a Windows `\r` included.
const HERMES_KEY = /^\s+(?:post_llm_call|on_session_finalize)\s*:\s*(?:#[^\n]*)?$/
const TOP_HOOKS = /^hooks\s*:\s*(?:#[^\n]*)?$/
const EMPTY_HOOKS = /^hooks\s*:\s*\{\s*\}\s*(?:#[^\n]*)?$/

const indentOf = (line: string): number => line.length - line.trimStart().length

const isContent = (line: string): boolean => line.trim() !== '' && !line.trimStart().startsWith('#')

// Whether the key on line `at` has anything under it (YAML lets a list sit at the key's own
// indent).
const hasChildren = (lines: string[], at: number): boolean => {
  const indent = indentOf(lines[at] ?? '')
  const next = lines.slice(at + 1).find(isContent)
  if (next === undefined) return false

  return indentOf(next) > indent || (indentOf(next) === indent && next.trimStart().startsWith('- '))
}

// Adding ours again keeps a `hooks:` that only held ours, so they go back where they were
// rather than to the end of the file.
// Our list items, each with the lines that continue it: a YAML dumper (Hermes' own setup,
// or a person tidying the file) writes our flow-style item in block style, its timeout on a
// line of its own. A comment or another line that names the script is no item of ours.
const hermesItems = (lines: readonly string[]): Array<[number, number]> => {
  const items: Array<[number, number]> = []
  lines.forEach((line, at) => {
    if (!line.trimStart().startsWith('- ')) return
    const indent = indentOf(line)
    let end = at + 1
    while (end < lines.length && isContent(lines[end] ?? '') && indentOf(lines[end] ?? '') > indent) end += 1
    if (lines.slice(at, end).some(one => isContent(one) && OURS.test(one))) items.push([at, end])
  })

  return items
}

const stripHermesHooks = (text: string, isKeepingTop: boolean): string => {
  const lines = text.split('\n')
  const drop = new Set<number>()
  for (const [start, end] of hermesItems(lines)) for (let index = start; index < end; index += 1) drop.add(index)
  const kept = lines.filter((_, at) => !drop.has(at))
  if (kept.length === lines.length) return text
  const keys = kept.filter((line, at) => !(HERMES_KEY.test(line) && !hasChildren(kept, at)))
  const rest = isKeepingTop ? keys : keys.filter((line, at) => !(TOP_HOOKS.test(line) && !hasChildren(keys, at)))

  return `${rest.join('\n').replace(/\n{3,}/g, '\n\n').replace(/\n+$/, '')}\n`.replace(/^\n$/, '')
}

export const withoutHermesHooks = (text: string): string => stripHermesHooks(text, false)

export const withHermesHooks = (text: string, events: Array<[string, string]>): string | null => {
  // Ours all there already, in whatever style Hermes last wrote them: nothing to change, so
  // a session start neither rewrites the file nor says it connected Hermes again.
  const lines0 = text.split('\n')
  const items = hermesItems(lines0).map(([start, end]) => lines0.slice(start, end).join('\n'))
  // A dumper folds a long command onto the next line at a space (PyYAML at 80 columns, the
  // way Hermes saves config.yaml, splits the Windows command), so a run of spaces and line
  // breaks counts as one space.
  const flat = (one: string): string => one.replace(/\s+/g, ' ')
  const isItemOf = (item: string, command: string): boolean =>
    [command, JSON.stringify(command), `'${command.replace(/'/g, "''")}'`].some(form => flat(item).includes(flat(form)))
  if (items.length === events.length && events.every(([, command]) => items.some(item => isItemOf(item, command)))) return text
  const base = stripHermesHooks(text, true)
  const item = (command: string): string => `- {command: ${JSON.stringify(command)}, timeout: 10}`
  // Lines of ours end the way the file's own lines do.
  const eol = text.includes('\r\n') ? '\r' : ''
  // An empty `hooks: {}` becomes a bare `hooks:` that ours go under.
  const lines = base
    .replace(/\n+$/, '')
    .split('\n')
    .map(line => (EMPTY_HOOKS.test(line) ? `${line.replace(/\{\s*\}\s*/, '').replace(/\s+(#|\r|$)/, ' $1').trimEnd()}${line.endsWith('\r') ? '\r' : ''}` : line))
  const at = lines.findIndex(line => /^hooks\s*:/.test(line))
  if (at === -1) {
    const added = ['hooks:', ...events.flatMap(([event, command]) => [`  ${event}:`, `    ${item(command)}`])].join(`${eol}\n`)
    return base.trim() === '' ? `${added}${eol}\n` : `${base.replace(/(?:\r?\n)+$/, '')}${eol}\n${eol}\n${added}${eol}\n`
  }
  if (!TOP_HOOKS.test(lines[at] ?? '')) return null
  let end = lines.findIndex((line, index) => index > at && isContent(line) && indentOf(line) === 0)
  if (end === -1) end = lines.length
  let insert = end
  while (insert - 1 > at && !isContent(lines[insert - 1] ?? '')) insert -= 1
  const firstChild = lines.slice(at + 1, end).find(isContent)
  const indent = firstChild === undefined ? 2 : indentOf(firstChild)
  for (const [event, command] of events) {
    const key = lines.findIndex((line, index) => index > at && index < end && indentOf(line) === indent && new RegExp(`^\\s*${event}\\s*:`).test(line))
    if (key === -1) {
      lines.splice(insert, 0, `${' '.repeat(indent)}${event}:${eol}`, `${' '.repeat(indent + 2)}${item(command)}${eol}`)
      insert += 2
      end += 2
      continue
    }
    const after = (lines[key] ?? '').replace(/^[^:]*:/, '').trim()
    if (after !== '' && !after.startsWith('#')) return null
    const next = lines.slice(key + 1, end).find(isContent)
    const nested = next !== undefined && (indentOf(next) > indent || (indentOf(next) === indent && next.trimStart().startsWith('- ')))
    lines.splice(key + 1, 0, `${' '.repeat(nested && next !== undefined ? indentOf(next) : indent + 2)}${item(command)}${eol}`)
    if (key < insert) insert += 1
    end += 1
  }

  return `${lines.join('\n')}\n`
}

export const agentHooks = (ctx: ConnectContext): AgentHook[] => {
  const opencodeHome = ctx.opencodeHome ?? join(ctx, '.config', 'opencode')
  const turn = (agent: string): string => reportCommand(ctx.script, agent, 'turn', ctx.isWindows)
  const end = (agent: string): string => reportCommand(ctx.script, agent, 'end', ctx.isWindows)

  return [
    {
      // Stop carries last_assistant_message; Codex asks the person to approve a new hook in
      // its /hooks before it runs.
      agent: 'codex',
      label: 'Codex',
      dir: ctx.codexHome,
      file: [ctx.codexHome, 'hooks.json'].join(ctx.sep),
      edit: jsonEdit(config =>
        withGroupedHook(withGroupedHook(config, 'Stop', turn('codex'), { timeout: 10 }), 'SessionEnd', end('codex'), { timeout: 3 }),
      ),
    },
    {
      // AfterAgent carries prompt and prompt_response. Hooks are on by default; timeout is in ms.
      agent: 'gemini',
      label: 'Gemini CLI',
      dir: join(ctx, '.gemini'),
      file: join(ctx, '.gemini', 'settings.json'),
      edit: jsonEdit(config =>
        withGroupedHook(
          withGroupedHook(config, 'AfterAgent', turn('gemini'), { name: 'agent-board', timeout: 5000 }),
          'SessionEnd',
          end('gemini'),
          { name: 'agent-board-end', timeout: 5000 },
        ),
      ),
    },
    {
      // afterAgentResponse carries the reply's text; stop carries none, but fires where the
      // CLI skips the other; sessionEnd ends the block.
      agent: 'cursor',
      label: 'Cursor',
      dir: join(ctx, '.cursor'),
      file: join(ctx, '.cursor', 'hooks.json'),
      edit: jsonEdit(config =>
        withFlatHook(withFlatHook(withFlatHook(config, 'afterAgentResponse', turn('cursor')), 'stop', turn('cursor')), 'sessionEnd', end('cursor')),
      ),
    },
    {
      // A file of its own in ~/.grok/hooks; Stop carries lastAssistantMessage. Timeout in s: on
      // Windows PowerShell alone takes most of a second to start, so the end hook gets 5.
      agent: 'grok',
      label: 'Grok Build',
      dir: ctx.grokHome,
      dirs: grokSigns(ctx),
      file: [ctx.grokHome, 'hooks', 'agent-board.json'].join(ctx.sep),
      old: [ctx.grokHome, 'hooks', 'progress-pane.json'].join(ctx.sep),
      generated: true,
      edit: generatedFile(
        writeConfig(withGroupedHook(withGroupedHook({}, 'Stop', turn('grok'), { timeout: 10 }), 'SessionEnd', end('grok'), { timeout: 5 })),
        [writeConfig(withGroupedHook(withGroupedHook({}, 'Stop', turn('grok'), { timeout: 10 }), 'SessionEnd', end('grok'), { timeout: 1 }))],
      ),
    },
    {
      // Muse wants schema_version 1 and no handler keys beyond type, command, timeout. The end
      // hook gets 5 s for the same reason as Grok's.
      agent: 'muse',
      label: 'Muse Code',
      dir: join(ctx, '.config', 'muse'),
      file: join(ctx, '.config', 'muse', 'settings.json'),
      edit: jsonEdit(config =>
        withGroupedHook(withGroupedHook({ schema_version: 1, ...config }, 'Stop', turn('muse'), { timeout: 10 }), 'SessionEnd', end('muse'), { timeout: 5 }),
      ),
    },
    {
      // post_llm_call carries the turn's words under `extra`. Its on_session_end fires after
      // every turn, so the end is on_session_finalize. Hermes asks once before it runs a new
      // hook (or takes --accept-hooks). Timeout in s.
      agent: 'hermes',
      label: 'Hermes Agent',
      dir: ctx.hermesHome,
      file: [ctx.hermesHome, 'config.yaml'].join(ctx.sep),
      edit: (text, remove) =>
        remove
          ? withoutHermesHooks(text)
          : withHermesHooks(text, [
              ['post_llm_call', turn('hermes')],
              ['on_session_finalize', end('hermes')],
            ]),
    },
    {
      // OpenClaw takes plugins, not commands. A standalone file goes in plugins.load.paths and
      // takes its file name as its id; it must come before the config entry that loads it.
      agent: 'openclaw',
      label: 'OpenClaw',
      dir: ctx.openclawHome,
      file: [ctx.openclawHome, OPENCLAW_FILE].join(ctx.sep),
      generated: true,
      edit: generatedFile(openclawPlugin(ctx)),
    },
    {
      agent: 'openclaw',
      label: 'OpenClaw',
      dir: ctx.openclawHome,
      file: [ctx.openclawHome, 'openclaw.json'].join(ctx.sep),
      edit: (text, remove) => {
        const config = readConfig(text)
        if (config === null) return null
        const file = [ctx.openclawHome, OPENCLAW_FILE].join(ctx.sep)
        // Nothing of ours to take out: the person's file stays byte for byte.
        if (remove && !hasOpenclawPlugin(config, file)) return text
        return writeChanged(text, config, remove ? withoutOpenclawPlugin(config, file) : withOpenclawPlugin(config, file))
      },
    },
    {
      agent: 'opencode',
      label: 'OpenCode',
      dir: opencodeHome,
      file: [opencodeHome, 'plugin', 'agent-board.js'].join(ctx.sep),
      old: [opencodeHome, 'plugin', 'progress-pane.js'].join(ctx.sep),
      generated: true,
      edit: generatedFile(opencodePlugin(ctx)),
    },
    ...boardCommands(ctx),
  ]
}

// OpenCode takes plugins, not commands: this one writes the session's last exchange into the
// inbox when the session goes idle (a subagent's session aside), and an end when it is
// deleted. Every export of a plugin file must be a function.
export const opencodePlugin = (ctx: ConnectContext): string => `// Written by the Agent Board plugin (/progress connect): reports each finished turn to the Agent Board
// pane.
import { mkdirSync, renameSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const INBOX = ${JSON.stringify(ctx.inbox)}

const save = (event, payload) => {
  try {
    mkdirSync(INBOX, { recursive: true })
    const name = \`opencode-\${event}-\${Date.now()}-\${process.pid}\`
    writeFileSync(join(INBOX, name + '.tmp'), JSON.stringify(payload))
    renameSync(join(INBOX, name + '.tmp'), join(INBOX, name + '.json'))
  } catch {}
}

const textOf = message =>
  (message?.parts ?? [])
    .filter(part => part.type === 'text' && !part.synthetic && !part.ignored)
    .map(part => part.text)
    .join('\\n')

export const AgentBoard = async ({ client, directory }) => ({
  event: async ({ event }) => {
    try {
      if (event.type === 'session.idle') {
        const id = event.properties.sessionID
        const session = await client.session.get({ path: { id } })
        if (session.data?.parentID) return
        const listed = await client.session.messages({ path: { id } })
        const messages = listed.data ?? []
        const last = role => [...messages].reverse().find(message => message.info?.role === role)
        save('turn', { session_id: id, cwd: directory, prompt: textOf(last('user')), last_assistant_message: textOf(last('assistant')) })
      } else if (event.type === 'session.deleted') {
        const id = event.properties.info?.id
        if (id) save('end', { session_id: id, cwd: directory })
      }
    } catch {}
  },
})
`

const OPENCLAW_ID = 'agent-board'
const OPENCLAW_FILE = `${OPENCLAW_ID}.mjs`

// The first OpenClaw whose config check takes plugins.entries.<id>.hooks.allowConversationAccess
// (its changelog, #71221). An older one will not start with our entry in its config. Seen live
// on 2026.3.8, which also wants a manifest beside a plugin file; by that changelog, 2026.4.23
// asks for the grant before agent_end but still refuses the key.
export const OPENCLAW_MIN = '2026.4.24'

// A version the way OpenClaw reads one (2026.4.24, v2026.4.24, 2026.4.24-beta.1) as one number
// to compare; null when it is not one.
const calver = (version: string): number | null => {
  const parts = /^v?(\d+)\.(\d+)\.(\d+)/.exec(version.trim())

  return parts === null ? null : Number(parts[1]) * 10000 + Number(parts[2]) * 100 + Number(parts[3])
}

// The version, when it is older than OPENCLAW_MIN; null when it is that or newer, or is not a
// version at all.
export const openclawTooOld = (version: string): string | null => {
  const at = calver(version)
  const min = calver(OPENCLAW_MIN)

  return at !== null && min !== null && at < min ? version.trim() : null
}

// The version that last saved an OpenClaw config (meta.lastTouchedVersion). Updating OpenClaw
// leaves it as it was until OpenClaw saves the file again.
export const openclawSavedBy = (text: string): string | null => {
  const config = readConfig(text)
  const version = config !== null && isRecord(config.meta) ? config.meta.lastTouchedVersion : undefined

  return typeof version === 'string' ? version : null
}

// The version `openclaw --version` prints: `OpenClaw 2026.3.8 (3caab92)`.
export const openclawPrinted = (stdout: string): string | null => /\bv?(\d+\.\d+\.\d+\S*)/.exec(stdout)?.[1] ?? null

const hasOpenclawPlugin = (config: Json, file: string): boolean => {
  const plugins = isRecord(config.plugins) ? config.plugins : {}
  const load = isRecord(plugins.load) ? plugins.load : {}
  const entries = isRecord(plugins.entries) ? plugins.entries : {}

  return (Array.isArray(load.paths) && load.paths.includes(file)) || OPENCLAW_ID in entries || (Array.isArray(plugins.allow) && plugins.allow.includes(OPENCLAW_ID))
}

// OpenClaw loads a plugin that is not bundled only when enabled, and passes it a turn's
// words (agent_end) only with allowConversationAccess. A restrictive plugins.allow list
// still wins, so ours joins it when there is one. OpenClaw writes this file as plain JSON;
// one hand-written as JSON5 is left alone.
export const withOpenclawPlugin = (config: Json, file: string): Json => {
  const plugins = isRecord(config.plugins) ? config.plugins : {}
  const load = isRecord(plugins.load) ? plugins.load : {}
  const paths = Array.isArray(load.paths) ? (load.paths as unknown[]) : []
  const entries = isRecord(plugins.entries) ? plugins.entries : {}
  const entry = isRecord(entries[OPENCLAW_ID]) ? (entries[OPENCLAW_ID] as Json) : {}
  const hooks = isRecord(entry.hooks) ? entry.hooks : {}
  const allow = Array.isArray(plugins.allow) && plugins.allow.length > 0 && !plugins.allow.includes(OPENCLAW_ID) ? { allow: [...plugins.allow, OPENCLAW_ID] } : {}

  return {
    ...config,
    plugins: {
      ...plugins,
      ...allow,
      load: { ...load, paths: paths.includes(file) ? paths : [...paths, file] },
      entries: { ...entries, [OPENCLAW_ID]: { ...entry, enabled: true, hooks: { ...hooks, allowConversationAccess: true } } },
    },
  }
}

export const withoutOpenclawPlugin = (config: Json, file: string): Json => {
  if (!isRecord(config.plugins)) return config
  const { load, entries, allow, ...rest } = config.plugins
  const plugins: Json = { ...rest }
  if (isRecord(load)) {
    const paths = Array.isArray(load.paths) ? (load.paths as unknown[]).filter(path => path !== file) : undefined
    const { paths: _, ...other } = load
    const kept = paths === undefined || paths.length === 0 ? other : { ...other, paths }
    if (Object.keys(kept).length > 0) plugins.load = kept
  } else if (load !== undefined) {
    plugins.load = load
  }
  if (isRecord(entries)) {
    const { [OPENCLAW_ID]: _, ...other } = entries
    if (Object.keys(other).length > 0) plugins.entries = other
  } else if (entries !== undefined) {
    plugins.entries = entries
  }
  if (Array.isArray(allow)) {
    const kept = allow.filter(id => id !== OPENCLAW_ID)
    if (kept.length > 0) plugins.allow = kept
  } else if (allow !== undefined) {
    plugins.allow = allow
  }

  return { ...config, plugins }
}

// Writes each finished turn into the inbox itself, as the OpenCode plugin does, so it needs
// no shell. Heartbeat and memory runs are OpenClaw talking to itself, not the person's work;
// a compaction or a restart does not end the session.
export const openclawPlugin = (ctx: ConnectContext): string => `// Written by the Agent Board plugin (/progress connect): reports each finished turn to the Agent Board
// pane.
import { mkdirSync, renameSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const INBOX = ${JSON.stringify(ctx.inbox)}

const save = (event, payload) => {
  try {
    mkdirSync(INBOX, { recursive: true })
    const name = \`openclaw-\${event}-\${Date.now()}-\${process.pid}\`
    writeFileSync(join(INBOX, name + '.tmp'), JSON.stringify(payload))
    renameSync(join(INBOX, name + '.tmp'), join(INBOX, name + '.json'))
  } catch {}
}

const textOf = message =>
  typeof message?.content === 'string'
    ? message.content
    : Array.isArray(message?.content)
      ? message.content.filter(part => part?.type === 'text').map(part => part.text).join('\\n')
      : ''

export default {
  id: '${OPENCLAW_ID}',
  name: 'Agent Board',
  register(api) {
    api.on('agent_end', (event, ctx) => {
      try {
        if (!ctx?.sessionId || ctx.trigger === 'heartbeat' || ctx.trigger === 'memory') return
        const messages = Array.isArray(event?.messages) ? event.messages : []
        const last = role => [...messages].reverse().find(message => message?.role === role)
        const answer = textOf(last('assistant'))
        if (answer.trim() === '') return
        save('turn', { session_id: ctx.sessionId, cwd: ctx.workspaceDir ?? '', prompt: textOf(last('user')), last_assistant_message: answer })
      } catch {}
    })
    api.on('session_end', (event, ctx) => {
      try {
        if (event?.reason === 'compaction' || event?.reason === 'restart') return
        const id = ctx?.sessionId ?? event?.sessionId
        if (id) save('end', { session_id: id, cwd: ctx?.workspaceDir ?? '' })
      } catch {}
    })
  },
}
`

// The standalone board, with the progress file and language of the session that wrote it
// set on its first line (an ES module's imports run first either way).
export const boardScript = (path: string, lang: string): string => `globalThis.AGENT_BOARD = ${JSON.stringify({ path, lang })}\n${BOARD_SCRIPT}`

// The language a board script already written prints in, from its first line; '' when it
// names none.
export const boardLangOf = (code: string): string => {
  const head = /^globalThis\.AGENT_BOARD = ([^\n]*)/.exec(code)
  try {
    const lang = (JSON.parse(head?.[1] ?? '') as { lang?: unknown } | null)?.lang
    return typeof lang === 'string' ? lang : ''
  } catch {
    return ''
  }
}

// What stands for this machine's paths in the hashes of hooks/released.ts. No file of ours
// holds a NUL, so a file only matches once its own paths are put back.
export const RELEASE_PATHS = { board: '\u0000board\u0000', inbox: '\u0000inbox\u0000' } as const

// A file an earlier release wrote, before the plugin kept a record of its output: with this
// machine's paths swapped for the placeholders, its bytes hash to one that release generated.
// An installation from any tagged release (0.17.1 on) upgrades silently this way, while a file the person
// edited by so much as a byte is still theirs.
export const isReleased = (kind: ReleasedKind, text: string, paths: { board?: string; inbox?: string } = {}): boolean => {
  let normal = text
  if (paths.board) normal = normalizeCommandPath(normal, paths.board, RELEASE_PATHS.board)
  if (paths.inbox) normal = normal.split(paths.inbox).join(RELEASE_PATHS.inbox)
  const hash = sha256(normal)

  return RELEASED.some(release => release[kind].includes(hash))
}

// The board script beside progress.md: its first line names this progress.md in one of the
// languages, and the rest is a released bundle.
export const isReleasedBoard = (text: string, path: string): boolean => {
  const cut = text.indexOf('\n')
  if (cut < 0) return false
  const head = text.slice(0, cut)
  if (!LANGS.some(lang => head === `globalThis.AGENT_BOARD = ${JSON.stringify({ path, lang })}`)) return false

  return isReleased('board', text.slice(cut + 1))
}

// The board script needs this Node.js or newer (the README says so): its commands run it, and
// so does the terminal board. The reporting hooks do not.
export const NODE_MIN = 18
// What `node --version` printed, when it is a version.
export const nodeVersionOf = (printed: string): string | null => {
  const version = printed.trim()
  return /^v\d+\.\d+\.\d+(?:-[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?$/.test(version) ? version : null
}
export const isNodeSupported = (version: string): boolean => Number(/^v(\d+)\./.exec(version)?.[1] ?? 0) >= NODE_MIN

// What a session start found for each agent here, so a written hook is never taken for a
// working board, and `/progress connect status` can say it again later.
export type HookState = 'configured' | 'failed' | 'unreadable' | 'tooOld'
export type BoardState = 'ready' | 'runtime' | 'failed' | 'none'
export type AgentSetup = { agent: string; label: string; hook: HookState | null; board: BoardState }
type ProblemArgs<T> = {
  [K in keyof T]: T[K] extends (...args: infer A) => string
    ? { readonly [I in keyof A]: A[I] extends string ? 'string' : A[I] extends number ? 'number' : never }
    : never
}
export const PROBLEM_ARGS = {
  connectPreserved: ['string'],
  connectRemoveFailed: ['string'],
  connectBoardRetained: ['string'],
  connectBoardReadFailed: ['string'],
  connectBoardFailed: ['string'],
  connectReporterFailed: ['string'],
  connectReadFailed: ['string', 'string'],
  connectSkipped: ['string', 'string'],
  connectFailed: ['string', 'string'],
  connectTooOld: ['string', 'string', 'string'],
  setupNodeMissing: ['number'],
  setupNodeOld: ['string', 'number'],
} as const satisfies Partial<ProblemArgs<Strings>>
export type SetupNotice = {
  [K in keyof typeof PROBLEM_ARGS]: { message: K; args: Parameters<Strings[K]> }
}[keyof typeof PROBLEM_ARGS]
export type SetupProblem = { key: string } & (SetupNotice | { text: string })
export type SetupState = { agents: AgentSetup[]; problems: SetupProblem[]; node: string | null }
type StoredSetupState = Omit<SetupState, 'problems'> & { problems: unknown[] }

const isSetupProblem = (value: unknown): value is SetupProblem => {
  if (typeof value !== 'object' || value === null) return false
  const one = value as Record<string, unknown>
  if (typeof one.key !== 'string') return false
  if (typeof one.text === 'string') return true
  if (typeof one.message !== 'string' || !Object.prototype.hasOwnProperty.call(PROBLEM_ARGS, one.message) || !Array.isArray(one.args)) return false
  const types: readonly string[] = PROBLEM_ARGS[one.message as keyof typeof PROBLEM_ARGS]
  return one.args.length === types.length && types.every((type, index) => typeof (one.args as unknown[])[index] === type)
}

// Earlier releases stored the words themselves; new records follow the session's language.
export const setupProblemText = (problem: SetupProblem, s: Strings = ZH_TW): string => {
  if ('text' in problem) return problem.text
  // The repeated branches exist only so the type checker sees each call's argument types.
  switch (problem.message) {
    case 'setupNodeMissing': return s[problem.message](...problem.args)
    case 'setupNodeOld': return s[problem.message](...problem.args)
    case 'connectTooOld': return s[problem.message](...problem.args)
    case 'connectReadFailed':
    case 'connectSkipped':
    case 'connectFailed': return s[problem.message](problem.args[0], problem.args[1])
    default: return s[problem.message](problem.args[0])
  }
}

// Of an agent's files, the worst one says how its hook came out: OpenClaw takes two.
const HOOK_RANK: Record<HookState, number> = { configured: 0, tooOld: 1, unreadable: 2, failed: 3 }
export const worseHook = (one: HookState, other: HookState): HookState => (HOOK_RANK[other] > HOOK_RANK[one] ? other : one)

// The agents each board file (`boardCommands`, by its agent) shows the board in.
export const BOARD_FOR: Record<string, readonly string[]> = {
  skills: ['codex', 'cursor', 'grok', 'openclaw', 'gemini', 'opencode', 'muse'],
  gemini: ['gemini'],
  opencode: ['opencode'],
  hermes: ['hermes'],
  antigravity: ['antigravity'],
}

// An agent's board command is ready when a board file it reads is in place and Node.js runs;
// one that could not be written, with none in place, failed. Antigravity has a board file and
// no hook.
export const setupAgents = (
  hooks: readonly Omit<AgentSetup, 'board'>[],
  boards: Partial<Record<string, 'ok' | 'failed'>>,
  isNodeReady: boolean,
): AgentSetup[] => {
  const all = boards.antigravity === undefined ? [...hooks] : [...hooks, { agent: 'antigravity', label: 'Antigravity', hook: null }]

  return all.map(one => {
    const read = Object.keys(BOARD_FOR).filter(file => BOARD_FOR[file]?.includes(one.agent)).map(file => boards[file])
    const board: BoardState = read.includes('ok') ? (isNodeReady ? 'ready' : 'runtime') : read.includes('failed') ? 'failed' : 'none'
    return { ...one, board }
  })
}

// The status, agent by agent: its hook, what the agent still asks of the person (Codex's
// approval, Hermes Agent's question, OpenClaw's restart), its board command, then the problems.
export const setupLines = (state: StoredSetupState, s: Strings = ZH_TW, withProblems = true): string[] => {
  const problems = state.problems.filter(isSetupProblem)
  const hookWords = (one: AgentSetup): string[] => {
    if (one.hook === null) return []
    if (one.hook !== 'configured') return [one.hook === 'unreadable' ? s.setupHookUnreadable : one.hook === 'tooOld' ? s.setupHookTooOld : s.setupHookFailed]
    const needs = one.agent === 'codex' ? [s.setupCodexTrust] : one.agent === 'hermes' ? [s.setupHermesTrust] : one.agent === 'openclaw' ? [s.setupOpenclawRestart] : []
    return [s.setupHookConfigured, ...needs]
  }
  const boardWords = (one: AgentSetup): string[] =>
    one.board === 'ready' ? [s.setupBoardReady] : one.board === 'runtime' ? [s.setupBoardNeedsNode(NODE_MIN)] : one.board === 'failed' ? [s.setupBoardFailed] : []

  return [
    s.setupStatusTitle,
    ...(state.agents.length === 0 ? (withProblems && problems.length > 0 ? [] : [s.connectNone]) : state.agents.map(one => s.setupAgent(one.label, [...hookWords(one), ...boardWords(one)]))),
    ...(withProblems ? problems.map(one => setupProblemText(one, s)) : []),
  ]
}

// The store holds what an earlier version, or a damaged write, may have left.
export const isSetupState = (value: unknown): value is StoredSetupState => {
  if (typeof value !== 'object' || value === null) return false
  const { agents, problems } = value as { agents?: unknown; problems?: unknown }
  const isObject = (one: unknown): one is Record<string, unknown> => typeof one === 'object' && one !== null
  const hooks: unknown[] = [null, 'configured', 'failed', 'unreadable', 'tooOld']
  const boards: unknown[] = ['ready', 'runtime', 'failed', 'none']
  return (
    Array.isArray(agents) &&
    agents.every(one => isObject(one) && typeof one.agent === 'string' && typeof one.label === 'string' && hooks.includes(one.hook) && boards.includes(one.board)) &&
    Array.isArray(problems)
  )
}

// Each agent's way to show the board, so the person sees every agent's work from whichever
// one they are in. Gemini CLI and OpenCode paste a command's output into the prompt before
// the model reads it; the others read skills, whose model runs the command. Most of them
// read ~/.agents/skills, so one skill there reaches Codex, Cursor, Grok Build, OpenClaw,
// Gemini CLI, OpenCode and Muse Code; Hermes Agent and Antigravity keep their own folder.
const SKILL = 'agent-board'

export const boardCommands = (ctx: ConnectContext): AgentHook[] => {
  if (ctx.board === undefined) return []
  const opencodeHome = ctx.opencodeHome ?? join(ctx, '.config', 'opencode')
  const run = boardRun(ctx.board)
  // JSON is YAML too, so a description with a colon in it stays one value.
  const contents = (s: Strings) => {
    const description = JSON.stringify(s.boardCommandDescription)
    const skill = (prompt: string): string => `---\nname: ${SKILL}\ndescription: ${description}\n---\n\n${prompt}\n`
    return {
      skill: skill(s.boardSkillPrompt(run)),
      // Hermes Agent answers in a chat app (Telegram), where a link to this computer does not open.
      hermes: skill(s.boardChatSkillPrompt(run)),
      gemini: geminiBoardCommand(s.boardCommandDescription, s.boardCommandPrompt, run),
      opencode: opencodeBoardCommand(s.boardCommandDescription, s.boardCommandPrompt, run),
    }
  }
  const current = contents(ctx.s ?? ZH_TW)
  // Before ownership records existed, a different session could have generated these
  // exact files in another supported language, or an earlier release could have. No other
  // bytes may differ.
  const known = Object.values(STRINGS).map(contents)
  const file = (kind: keyof typeof current) =>
    generatedFile(current[kind], text => known.some(one => one[kind] === text) || isReleased(kind === 'hermes' ? 'skill' : kind, text, { board: ctx.board ?? '' }))

  return [
    {
      agent: 'skills',
      label: '',
      dir: ctx.codexHome,
      dirs: [ctx.codexHome, join(ctx, '.cursor'), ...grokSigns(ctx), ctx.openclawHome, join(ctx, '.gemini'), opencodeHome, join(ctx, '.config', 'muse')],
      file: join(ctx, '.agents', 'skills', SKILL, 'SKILL.md'),
      generated: true,
      edit: file('skill'),
    },
    { agent: 'gemini', label: '', dir: join(ctx, '.gemini'), file: join(ctx, '.gemini', 'commands', 'board.toml'), generated: true, edit: file('gemini') },
    { agent: 'opencode', label: '', dir: opencodeHome, file: [opencodeHome, 'commands', 'board.md'].join(ctx.sep), generated: true, edit: file('opencode') },
    { agent: 'hermes', label: '', dir: ctx.hermesHome, file: [ctx.hermesHome, 'skills', SKILL, 'SKILL.md'].join(ctx.sep), generated: true, edit: file('hermes') },
    {
      // Antigravity reads its skills here; it has no turn-end hook of its own, so it only shows
      // the board.
      agent: 'antigravity',
      label: '',
      dir: join(ctx, '.gemini', 'antigravity'),
      file: join(ctx, '.gemini', 'config', 'skills', SKILL, 'SKILL.md'),
      generated: true,
      edit: file('skill'),
    },
  ]
}

files.hooks/inbox.ts:
import { baseName } from './parse'
import { STRINGS } from './strings'

// What another agent's hook handed over at the end of a turn or a session, saved by the
// reporter script as one file in the inbox (`<agent>-<turn|end>-<time>-<pid>.json`). Every
// agent names its fields its own way; this reads the ones they use.

export type AgentTurn = {
  agent: string
  event: 'turn' | 'end'
  // The agent's own session id, and the 8-hex id its block goes by.
  session: string
  id: string
  cwd: string
  project: string
  prompt: string
  answer: string
  transcript: string
  // When the turn ended, normalized to milliseconds from the reporter's file name.
  at?: number
}

// Inbox file names: agent, event, then anything. Lower-case letters, digits and dashes only.
const NAME = /^([a-z][a-z0-9]*)-(turn|end)-[\w.-]+\.json$/

export const isInboxFile = (name: string): boolean => NAME.test(name)

// Oldest first by the time in the name; in the same second a turn comes before its session's
// end (Codex writes both within one second when `codex exec` finishes).
export const inboxOrder = (a: string, b: string): number => {
  const parts = (name: string): [number, number] => {
    const found = /^[a-z0-9]+-(turn|end)-(\d+)/.exec(name)
    return [inboxTime(name) ?? 0, found?.[1] === 'end' ? 1 : 0]
  }
  const [timeA, endA] = parts(a)
  const [timeB, endB] = parts(b)

  return timeA - timeB || endA - endB || a.localeCompare(b)
}

// Words sit a few levels down in every agent's payload. Another program writes the file, and
// one nested a hundred thousand deep would overflow the stack and leave the files taken with
// it unread, so the search stops well short of that.
const DEPTH_MAX = 32

const text = (value: unknown, depth = 0): string => {
  if (typeof value === 'string') return value
  if (depth >= DEPTH_MAX) return ''
  if (Array.isArray(value)) {
    for (let index = value.length - 1; index >= 0; index -= 1) {
      const found = text(value[index], depth + 1)
      if (found.trim() !== '') return found
    }
    return ''
  }
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>
    for (const key of ['text', 'content', 'message']) {
      const found = text(record[key], depth + 1)
      if (found.trim() !== '') return found
    }
  }

  return ''
}

const first = (record: Record<string, unknown>, keys: readonly string[]): string => {
  for (const key of keys) {
    const found = text(record[key])
    if (found.trim() !== '') return found.trim()
  }

  return ''
}

// FNV-1a, so one agent session always maps to the same block id.
export const blockId = (agent: string, session: string): string => {
  let hash = 0x811c9dc5
  for (const char of `${agent}:${session}`) {
    hash ^= char.codePointAt(0) ?? 0
    hash = Math.imul(hash, 0x01000193) >>> 0
  }

  return hash.toString(16).padStart(8, '0')
}

// Hermes Agent's on_session_end comes after every turn; its on_session_finalize is the end.
const END_EVENTS = /^(?:session[-_]?end|sessionend|session\.deleted|on_session_finalize)$/i

const OPENCLAW_WORKSPACE = /[\\/]\.openclaw[\\/]workspace(?:-[^\\/]*)?[\\/]*$/

// One inbox file read; null when it is not JSON or names no session.
export const readTurn = (fileName: string, body: string): AgentTurn | null => {
  const name = NAME.exec(fileName)
  if (name === null) return null
  let parsed: unknown
  try {
    // Cursor on Windows starts its JSON with a byte-order mark.
    parsed = JSON.parse(body.replace(/^\uFEFF/, ''))
  } catch {
    return null
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return null
  // Hermes Agent puts each event's own fields under `extra`.
  const extra = (parsed as Record<string, unknown>).extra
  const record = { ...(extra !== null && typeof extra === 'object' && !Array.isArray(extra) ? (extra as Record<string, unknown>) : {}), ...(parsed as Record<string, unknown>) }
  // Grok Build also runs Cursor's hooks; its camelCase fields say whose turn it really is.
  const agent = typeof record.hookEventName === 'string' && 'workspaceRoot' in record ? 'grok' : (name[1] ?? 'agent')
  const session = first(record, ['session_id', 'sessionId', 'sessionID', 'thread-id', 'thread_id', 'conversation_id', 'conversationId'])
  if (session === '') return null
  const roots = record.workspace_roots
  const cwd = first(record, ['cwd', 'workspaceRoot', 'workspace', 'project_dir', 'directory']) || (Array.isArray(roots) ? text(roots[0]) : '')
  const hookEvent = first(record, ['hook_event_name', 'hookEventName', 'event', 'type'])
  // Grok Build sends one more Stop as a session closes; it ends the session, it is no turn.
  const closing = typeof record.reason === 'string' && /^(?:channel_closed|shutdown)$/.test(record.reason)
  const event = name[2] === 'end' || END_EVENTS.test(hookEvent) || closing ? 'end' : 'turn'
  const answer = first(record, ['last_assistant_message', 'lastAssistantMessage', 'last-assistant-message', 'prompt_response', 'assistant_response', 'response', 'text'])

  return {
    agent,
    event,
    session,
    id: blockId(agent, session),
    cwd,
    // OpenClaw's turns run in its own workspace folder, whose name says nothing. The name
    // becomes a `##` heading, so a folder name with a line break or a comment opening in it
    // cannot start a line or hide the lines after it. blocks.ts cleans a Claude session's
    // folder the same way, so both join one heading.
    project: OPENCLAW_WORKSPACE.test(cwd) ? 'OpenClaw' : baseName(cwd).replace(/<!--|-->/g, ' ').replace(/\s+/g, ' ').trim(),
    prompt: first(record, ['prompt', 'user_prompt', 'user_message', 'input-messages', 'input_messages', 'last_user_message']),
    // Gemini CLI says this when the turn had no text.
    answer: answer === '[no response text]' ? '' : answer,
    transcript: first(record, ['transcript_path', 'transcriptPath']),
    at: inboxTime(fileName),
  }
}

// Shell reporters use Unix seconds; PowerShell uses milliseconds. Their current
// epochs differ by three digits. Normalize before comparing or persisting order.
const milliseconds = (time: number): number => time < 1e12 ? time * 1000 : time

// The time in an inbox file's name, in milliseconds, or undefined when it holds none.
export const inboxTime = (fileName: string): number | undefined => {
  const found = /^[a-z0-9]+-(?:turn|end)-(\d+)/.exec(fileName)

  const at = found === null ? NaN : Number(found[1])
  return Number.isSafeInteger(at) ? milliseconds(at) : undefined
}

// v0.19.1 stored raw seconds or milliseconds, doubled with an end-event bit.
// Keep that bit while migrating old mirrors; otherwise an upgrade could replay
// an older seconds event over a newer, already stored seconds event.
export const normalizeTurnOrder = (order: unknown): number | undefined =>
  typeof order !== 'number' || !Number.isSafeInteger(order) || order < 0 ? undefined : milliseconds(Math.floor(order / 2)) * 2 + order % 2

// Where a turn falls in its session, as inboxOrder sorts files: by time, and in the same
// second a turn before its session's end (Codex writes both within one second).
export const turnOrder = (turn: Pick<AgentTurn, 'at' | 'event'>): number | undefined =>
  turn.at === undefined ? undefined : milliseconds(turn.at) * 2 + (turn.event === 'end' ? 1 : 0)

// One line of a session log as a speaker and their words. Grok Build's log is ACP updates,
// which stream a message in chunks.
type LogEntry = { role: string; words: string; isChunk: boolean }

const logEntry = (line: string): LogEntry | null => {
  let entry: unknown
  try {
    entry = JSON.parse(line)
  } catch {
    return null
  }
  if (entry === null || typeof entry !== 'object') return null
  const record = entry as Record<string, unknown>
  const params = record.params as Record<string, unknown> | undefined
  const update = params?.update as Record<string, unknown> | undefined
  if (update !== undefined && typeof update.sessionUpdate === 'string') {
    const kind = /^(user|agent)_message_chunk$/.exec(update.sessionUpdate)
    const content = update.content as Record<string, unknown> | undefined
    return kind === null ? null : { role: kind[1] === 'user' ? 'user' : 'assistant', words: text(content?.text), isChunk: true }
  }
  const inner = (record.message ?? record.payload ?? record) as Record<string, unknown>
  const role = String(inner.role ?? record.role ?? record.type ?? '')

  return { role, words: text(inner.content ?? inner.text ?? record.content ?? record.text), isChunk: false }
}

// The end of a session log, as text the model can read: the last assistant and user words
// it can find in JSON lines, else, for a log written as plain text, the raw tail. A JSON
// file with no words in it is no log (a key file, a config), so none of it goes to the model.
// Only the end of a log is read: a long Codex rollout runs to tens of megabytes, and the last
// exchange is all that is wanted.
export const LOG_TAIL = 256 * 1024

export const transcriptTail = (log: string, limit = 3000, isText = false): { prompt: string; answer: string } => {
  const tail = log.length > LOG_TAIL ? log.slice(log.indexOf('\n', log.length - LOG_TAIL) + 1) : log
  const lines = tail.split(/\r?\n/).filter(line => line.trim() !== '')
  // Chunks of one message, one after another, read as the whole message.
  const entries: LogEntry[] = []
  for (const line of lines) {
    const entry = logEntry(line)
    if (entry === null) continue
    const last = entries.at(-1)
    if (entry.isChunk && last !== undefined && last.isChunk && last.role === entry.role) entries[entries.length - 1] = { ...last, words: last.words + entry.words }
    else entries.push(entry)
  }
  let prompt = ''
  let answer = ''
  for (let index = entries.length - 1; index >= 0 && (prompt === '' || answer === ''); index -= 1) {
    const { role, words: raw } = entries[index] ?? { role: '', words: '' }
    const words = raw.trim()
    if (words === '') continue
    if (answer === '' && /assistant|model|agent/i.test(role)) answer = words
    else if (prompt === '' && /user|human/i.test(role) && answer !== '') prompt = words
  }
  if (answer === '' && isText) answer = lines.slice(-20).join('\n')

  return { prompt: prompt.slice(-1200), answer: answer.slice(-limit) }
}

// Cursor writes its session logs as plain text, in its agent-transcripts folder; every other
// agent's are JSON. Any other text file an inbox file names (a list of recovery codes) is
// not read out raw.
export const isTextLog = (path: string): boolean => /[\\/]agent-transcripts[\\/][^\\/]+\.txt$/i.test(path)

// A session log the pane may open: the path comes from a file anyone on the machine can drop
// into the inbox, so only the kinds agents write their logs in (JSON lines; Cursor's are
// text; older Gemini CLI writes chats/session-*.json), never a key, an env file or another
// JSON file such as ~/.claude/.credentials.json or ~/.gemini/oauth_creds.json, and no
// climbing out of a folder. A JSON file that holds no conversation gives the model nothing,
// and only Cursor's own transcripts are read out as raw text (transcriptTail, isTextLog).
export const isTranscriptPath = (path: string): boolean =>
  (/\.(?:jsonl|txt)$/i.test(path) || /[\\/]chats[\\/][^\\/]+\.json$/i.test(path)) && !/(?:^|[\\/])\.\.(?:[\\/]|$)/.test(path)

// How much of a turn a stored mirror keeps: the end of the last reply (what the next turn is
// compared with) and the start of the first request (what the model names the work from).
export const ANSWER_KEEP = 3000
export const PROMPT_KEEP = 1200

export const answerKey = (answer: string): string => answer.trim().slice(-ANSWER_KEEP)

export const promptKey = (prompt: string): string => prompt.trim().slice(0, PROMPT_KEEP)

// Of one agent session's files in a drain, the turns worth a model call: the last `keep`
// turns. A burst of older ones (a pane closed for a day) only moves the bookkeeping on, so
// one drain never makes dozens of calls.
export const turnsToDigest = (turns: readonly AgentTurn[], keep = 2): Set<number> => {
  const indexes = turns.flatMap((turn, index) => (turn.event === 'turn' ? [index] : []))

  return new Set(indexes.slice(-keep))
}

// The inbox files already taken, by name, each stamped `<session>:<time>`: three days of
// them, at most the newest `max`, so the record stays small however busy the agents are.
export const keepInboxDone = (done: Readonly<Record<string, string>>, now: number, max = 2000): Record<string, string> => {
  const at = (stamp: string): number => Number(stamp.split(':')[1] ?? 0)
  const recent = Object.entries(done).filter(([, stamp]) => now - at(stamp) < 3 * 24 * 60 * 60 * 1000)

  return Object.fromEntries(recent.sort((a, b) => at(b[1]) - at(a[1])).slice(0, max))
}

// A file one session took for itself by renaming it:
// `<inbox name>.<session>-<when, base 36>-<attempt>.taking`. Another session's rename of the
// same file fails, so one session at a time reads it. It stays taken until what it reports is
// on the board: a file whose session closed half-way, or whose turn the board or the model
// could not take, is taken again once CLAIM_MS have passed, and set aside as
// `<inbox name>.failed` after MAX_TRIES attempts, kept rather than deleted.
export const CLAIM_MS = 15 * 60 * 1000
export const MAX_TRIES = 8

export const takenName = (name: string, session: string, at: number, attempt = 1): string =>
  `${name}.${session.replace(/\W/g, '') || 'x'}-${Math.max(0, Math.floor(at)).toString(36)}-${attempt}.taking`

export type Claim = { name: string; at: number | null; attempt: number }

// What a taken file's name says. A name from before claims carried their time
// (`<inbox name>.<session>.taking`) has none.
export const readClaim = (file: string): Claim | null => {
  const found = /^(.+\.json)\.([\w-]+?)(?:-([0-9a-z]+)-(\d+))?\.taking$/.exec(file)
  if (found === null || !isInboxFile(found[1] ?? '')) return null
  const at = found[3] === undefined ? null : parseInt(found[3], 36)

  return { name: found[1] ?? '', at, attempt: found[4] === undefined ? 1 : Math.max(1, Number(found[4])) }
}

export const isTakenFile = (name: string): boolean => readClaim(name) !== null

export const failedName = (name: string): string => `${name}.failed`

// What a session does with a file another look left taken: leave it to the session that may
// still be on it, take it again, or set it aside. A claim without a time goes by the file's
// own time and a day, the wait the older sweep gave it.
export const claimAction = (claim: Claim, mtimeMs: number, now: number): 'leave' | 'retake' | 'setAside' => {
  const isLeft = claim.at === null ? now - mtimeMs > 24 * 60 * 60 * 1000 : now - claim.at > CLAIM_MS
  if (!isLeft) return 'leave'

  return claim.attempt >= MAX_TRIES ? 'setAside' : 'retake'
}

// Why the files the board could not take are still in the inbox, by inbox name: `<attempt>:<time>:<why>`.
// The newest `max` are kept.
export const keepInboxFailed = (failed: Readonly<Record<string, string>>, max = 200): Record<string, string> => {
  const at = (note: string): number => Number(note.split(':')[1] ?? 0)

  return Object.fromEntries(Object.entries(failed).sort((a, b) => at(b[1]) - at(a[1])).slice(0, max))
}

// A turn that only showed the person the board (Gemini CLI's and OpenCode's /board, the
// agent-board skill): looking at the board is not work, so it gets no block of its own.
const BOARD_ASKS = /^\s*(?:\/board|[$/]agent-board)\s*$/

// The words of each language's board command and skill, around the command they name; a
// request that only mentions the script (someone working on this repository) is real work.
// The skill names its command twice (chat app first, then the page): the words after each, so
// the last ones are the sentence every earlier release wrote and a skill installed by one is
// still known.
const BOARD_WORDS = Object.values(STRINGS).flatMap(s =>
  [s.boardCommandPrompt, ...s.boardSkillPrompt('\u0000').split('\u0000').slice(1), ...s.boardChatSkillPrompt('\u0000').split('\u0000').slice(1)].filter(words => words.trim() !== ''),
)

// An agent can pick the board skill from plain words ("where do things stand?"), and then only
// the reply tells. The skill asks for the board first and one sentence on what needs the
// person after it; work done in the same turn is told before the board, or as more than a
// sentence after it.
// Each count takes all its digits and each gap stops at the next mark, and only a short line is
// tried: another agent writes the reply, and a long line of marks or digits with no ✓ at the
// end must not keep the inbox busy.
const BOARD_COUNTS = /●\s*\d+(?!\d)[^\n▸]*▸\s*\d+(?!\d)[^\n⚑]*⚑\s*\d+(?!\d)[^\n✓]*✓\s*\d+/
const COUNTS_MAX = 400
// What boardText prints below its count line: blank or indented lines, a section or project
// under its mark, and the line for nothing waiting or nothing open.
const BOARD_PLAIN = new Set(Object.values(STRINGS).flatMap(s => [s.nothingForYou, s.empty]))
const isBoardLine = (line: string): boolean => /^(?:\s|[●▸⚑◐] |$)/.test(line) || BOARD_PLAIN.has(line.trim())
const BOARD_LEAD = 40
const BOARD_ASIDE = 160
const BOARD_LINK = /https?:\/\/(?:127\.0\.0\.1|localhost):\d{1,5}\/\?t=[\w-]{1,64}/
// A CJK character says about as much as two Latin ones.
const weight = (text: string): number => [...text.trim()].reduce((sum, char) => sum + (/[ᄀ-ᅟ⺀-꓏가-힣豈-﫿︰-﹏＀-｠￠-￦]/.test(char) ? 2 : 1), 0)

// Before the board, only a short line that leads into it: words that point at the board, then
// a colon ("Here is where things stand:", 「目前所有專案的進度：」). Anything else told there,
// however short, is work: a look taken for work leaves a block the person sees and archives,
// while work taken for a look is dropped without a word. 目前 and 現在 also open a report
// told with no comma (「目前已修好 429 看板如下：」), so a lead holding a word for work done is
// work. 了 stays whole there: after any verb it says something was done (改了, 跑了), and
// narrowing it to 好了 and 完成了 would drop that turn's work to spare a block. An English lead
// can say so too (`Status: fixed 429:`); `updated` is left out, since it names a board
// (`Here's the updated board:`) as often as it reports work.
const LEAD_WORDS = /^(?:here\b|below\b|this is\b|where\b|current\b|progress\b|status\b|summary\b|(?:the )?(?:agent )?board\b|以下|下面|目前|這是|这是|現在|现在|進度|进度|看板)/i
const DONE_WORDS = /[已了]|完成|修好|加好|改好|做好|\b(?:fixed|added|changed|merged|removed|wrote|ran)\b/i

const isLeadIn = (text: string): boolean => {
  const lead = text.replace(/[*_]/g, '').trim()

  return lead === '' || (weight(lead) <= BOARD_LEAD && LEAD_WORDS.test(lead) && /^[^\n,，、;；.。!！?？—–]*[:：]$/.test(lead) && !/\s-\s/.test(lead) && !DONE_WORDS.test(lead))
}

export const isBoardAnswer = (answer: string): boolean => {
  // The line with the board page's address (`--serve`) goes with the board, after it or inside
  // the code block the board is shown in.
  const lines = answer.replace(/\r\n/g, '\n').split('\n').filter(line => !BOARD_LINK.test(line))
  const at = lines.findIndex(line => line.length <= COUNTS_MAX && BOARD_COUNTS.test(line))
  if (at < 0) return false
  let end = at + 1
  while (end < lines.length && isBoardLine(lines[end] ?? '')) end += 1
  let from = at
  let open = at - 1
  while (open >= 0 && (lines[open] ?? '').trim() === '') open -= 1
  // A fence goes with the board only when it holds the board and nothing else; blank lines
  // inside it are the board's.
  if (/^\s*```/.test(lines[open] ?? '')) {
    if (!/^\s*```\s*$/.test(lines[end] ?? '')) return false
    from = open
    end += 1
  }
  const before = lines.slice(0, from).join('\n')
  const after = lines.slice(end).join('\n')
  // A code block or a list beside the board (a test log, a diff, what was done) is work.
  // The indent stays on its line, so a run of blank lines is not crossed again from each one.
  const isAside = (text: string): boolean => !/```|^[ \t]*(?:[-*+]|\d+[.)])\s/m.test(text)

  return isLeadIn(before) && weight(after) <= BOARD_ASIDE && isAside(before) && isAside(after)
}

export const isBoardTurn = (turn: AgentTurn): boolean =>
  turn.event === 'turn' &&
  (BOARD_ASKS.test(turn.prompt) || /<name>agent-board<\/name>/.test(turn.prompt) || BOARD_WORDS.some(words => turn.prompt.includes(words)) || isBoardAnswer(turn.answer))

