    current: mine === null ? null : currentOf(mine, s),
    pr: prView(mine, s),
    overview: { waiting: asks.length, active: rows.length + due.length, due: due.length, today, idle: idle.length },
    focus,
    waiting: asks,
    hidden,
    idle,
    due: dueRows,
    active: rows,
    groups,
    recent: recent.slice(0, 3).map(({ at: _at, ...item }) => item),
