export const AgentBoardLocal = async ({ client }) => ({
  event: async ({ event }) => {
    const p = event.properties ?? {}
    const session = p.sessionID ?? p.info?.id
    if (!session || !['session.created', 'session.status', 'session.idle', 'session.deleted'].includes(event.type)) return
    if (event.type === 'session.status' && !['busy', 'retry', 'idle'].includes(p.status?.type)) return
    const info = event.type === 'session.deleted' ? { data: p.info } : await client.session.get({ path: { id: session } })
    if (!info.data || info.error || info.data.id !== session || info.data.parentID) return
    const state = event.type === 'session.deleted' ? 'ended' : event.type === 'session.status' && p.status?.type !== 'idle' ? 'working' : 'waiting'
    run('--agent-status', { session_id: session, state })
  },
  tool: {
    agent_board_progress: tool({
      description: ${JSON.stringify(description)},
      args: { title: tool.schema.string(), project: tool.schema.string(), state: tool.schema.enum(['working', 'waiting', 'done', 'ended']), steps: tool.schema.array(tool.schema.string()) },
      execute: async (args, context) => run('--codex-report', args, context.sessionID),
    }),
  },
})
`;

// hooks/portable-agents.ts
var runner = (node, script, progress, agent) => `import { spawnSync } from 'node:child_process'
const report = (mode, payload) => {
  const result = spawnSync(${JSON.stringify(node)}, [${JSON.stringify(script)}, mode, '--agent', '${agent}', '--progress-file', ${JSON.stringify(progress)}], {
    input: JSON.stringify(payload), encoding: 'utf8', windowsHide: true, timeout: 1500,
  })
  if (result.error || result.status !== 0) throw new Error('AGENT_BOARD_REPORT_FAILED')
}
`;
var openclawLocalPlugin = (node, script, progress) => `${runner(node, script, progress, "openclaw")}
export default {
  id: 'agent-board-local',
  register(api) {
    if (typeof api.agent?.events?.registerAgentEventSubscription !== 'function') throw new Error('AGENT_BOARD_HOST_API_UNSUPPORTED')
    api.on('session_start', event => report('--codex-event', { session_id: event.sessionId, hook_event_name: 'SessionStart' }))
    api.on('session_end', event => {
      if (['compaction', 'restart'].includes(event.reason)) return
      report('--codex-event', { session_id: event.sessionId, hook_event_name: 'SessionEnd' })
    })
    api.agent.events.registerAgentEventSubscription({
      id: 'agent-board-local-status', streams: ['lifecycle'], phases: ['start', 'end', 'error'], payload: 'metadata',
      handle(event) {
        if (event.stream !== 'lifecycle' || !event.sessionId || !event.runId) return
        const phase = event.data?.phase
        if (!['start', 'end', 'error'].includes(phase)) return
        report('--codex-event', { session_id: event.sessionId, turn_id: event.runId, hook_event_name: phase === 'start' ? 'UserPromptSubmit' : 'Stop' })
      },
    })
  },
}
`;
var deepseekLocalPlugin = (node, script, progress) => `${runner(node, script, progress, "deepseek")}
export const name = 'agent-board-local'
export const apply = ctx => {
  const save = (agent, state) => {
    try { report('--agent-status', { session_id: agent.session.header.id, state }) }
    catch { ctx.logger.warn('AGENT_BOARD_REPORT_FAILED') }
  }
  ctx.on('agent/created', ({ agent }) => { save(agent, agent.status === 'running' ? 'working' : 'waiting') })
  ctx.on('agent/status', ({ agent, status }) => {
    if (!['running', 'idle'].includes(status)) return
    save(agent, status === 'running' ? 'working' : 'waiting')
  })
  ctx.on('agent/disposed', ({ agent }) => { save(agent, 'ended') })
}
`;
var deepseekPatch = (text, owned, plugin, remove) => {
  const start = `# agent-board-local:start
`;
  const end = `# agent-board-local:end
`;
  const group = `${start}- insert:
    - id: agent-board-local
      name: ${JSON.stringify(plugin)}
${end}`;
  const old = typeof owned === "string" ? owned : null;
  if (old !== null && (text.split(old).length !== 2 || !old.startsWith(start) || !old.endsWith(end)))
    return { text, conflict: true };
  const stripped = old === null ? text : text.replace(old, "");
  if (stripped.includes("agent-board-local"))
