  const empty = stripped.trim() === "[]";
  if (!empty && stripped.split(/\r?\n/).some((line) => /\S/.test(line) && !/^\s|^#|^- /.test(line)))
    return { text, conflict: true };
  if (remove)
    return { text: stripped, conflict: false };
  if (old !== null)
    return { text: text.replace(old, group), group, conflict: false };
  return { text: `${empty ? "" : stripped}${stripped && !stripped.endsWith(`
`) && !empty ? `
` : ""}${group}`, group, conflict: false };
};

// scripts/codex-host.ts
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { isAbsolute, join, resolve } from "node:path";
var client = (executable) => {
  if (!isAbsolute(executable))
    throw new Error("ABSOLUTE_CODEX_BINARY_REQUIRED");
  const child = /\.m?js$/i.test(executable) ? spawn(process.execPath, [executable, "app-server", "--stdio"], { windowsHide: true }) : spawn(executable, ["app-server", "--stdio"], { windowsHide: true });
  let next = 0, buffer = "";
  const pending = new Map;
  const fail = () => {
    for (const item of pending.values()) {
      clearTimeout(item.timer);
      item.reject(new Error("CODEX_CONTROL_UNAVAILABLE"));
    }
    pending.clear();
  };
  child.on("error", fail);
  child.on("exit", fail);
  child.stderr.on("data", () => {
    return;
  });
  child.stdin.on("error", fail);
  child.stdout.on("data", (chunk) => {
    buffer += String(chunk);
    if (buffer.length > 2 * 1024 * 1024) {
      fail();
      child.kill();
      return;
    }
    for (;; ) {
      const end = buffer.indexOf(`
`);
      if (end < 0)
        break;
      const line = buffer.slice(0, end);
      buffer = buffer.slice(end + 1);
      let value;
      try {
        value = JSON.parse(line);
      } catch {
        continue;
      }
      const item = value.id === undefined ? undefined : pending.get(value.id);
      if (!item)
        continue;
      pending.delete(value.id);
      clearTimeout(item.timer);
      if (value.error)
        item.reject(new Error("CODEX_CONTROL_REJECTED"));
      else
        item.resolve(value.result ?? {});
    }
  });
  const request = (method, params) => new Promise((done, reject) => {
    const id = ++next;
    const timer = setTimeout(() => {
      pending.delete(id);
      reject(new Error("CODEX_CONTROL_TIMEOUT"));
    }, 5000);
    pending.set(id, { resolve: done, reject, timer });
    child.stdin.write(`${JSON.stringify({ id, method, params })}
`);
  });
  return {
    request,
    initialize: async () => {
      await request("initialize", { clientInfo: { name: "agent-board-hook-trust", version: "1" }, capabilities: { experimentalApi: true } });
      child.stdin.write(`${JSON.stringify({ method: "initialized", params: {} })}
`);
    },
    close: () => {
      child.kill();
      fail();
    }
  };
};
var trustCodex = async (executable, config, groups, apply) => {
  const before = readFileSync(config, "utf8");
