  if (expected.length !== 6)
    throw new Error("SIX_OWNED_HOOKS_REQUIRED");
  const control = client(executable);
  try {
    await control.initialize();
    const list = async () => {
      const response = await control.request("hooks/list", { cwds: [process.cwd()] });
      const data = response.data;
      if (!Array.isArray(data) || data.some((entry) => entry.errors?.length))
        throw new Error("HOOK_DISCOVERY_FAILED");
      const hooks = data.flatMap((entry) => entry.hooks).filter((hook) => resolve(hook.sourcePath) === resolve(config) && expected.some((one) => one.event === hook.eventName && one.command === hook.command));
      if (hooks.length !== 6 || new Set(hooks.map((hook) => hook.eventName)).size !== 6)
        throw new Error("OWNED_HOOKS_NOT_FOUND");
      if (hooks.some((hook) => !hook.enabled || !/^sha256:[a-f0-9]{64}$/.test(hook.currentHash)))
        throw new Error("HOOK_DISABLED_OR_HASH_UNSUPPORTED");
